/** The link mode labels of an effect; `never` for an effect with no choice of it. */
export type EffectLinkModeLabel<E extends EffectId> =
    E extends "miso.compressor" ? "dual_mono" | "maximum" | "average" :
    E extends "miso.de-esser" ? "dual_mono" | "maximum" | "average" :
    E extends "miso.dynamic-eq" ? "dual_mono" | "maximum" | "average" :
    E extends "miso.gate-expander" ? "dual_mono" | "maximum" | "average" :
    E extends "miso.multiband-compressor" ? "dual_mono" | "maximum" | "average" :
    E extends "miso.transient-shaper" ? "dual_mono" | "maximum" | "average" :
    E extends "miso.true-peak-limiter" ? "dual_mono" | "maximum" :
    never;

/**
 * The edits of one effect instance: each parameter, its bypass and its link mode, as `edit.set`
 * over the row of the instance's own control table. The parameter keys are the catalog's names.
 */
export abstract class EffectControlBuilders<E extends EffectId> {
  protected abstract readonly effectId: E;

  /** `edit.set` over this instance's address: the row's machine name, the lane and the ramp. */
  protected abstract setRow(
    control: string,
    value: number,
    lane: ControlLane,
    options?: SetControlOptions,
  ): ControlEditSet;

  parameter<N extends LiveEffectParameterName<E>>(
    name: N,
    value: LiveEffectParameterValue<E, N>,
    options?: LiveEffectParameterOptions<E, N>,
  ): ControlEditSet;
  parameter(edit: LiveEffectParameterEdit<E>): ControlEditSet;
  parameter(
    keyOrEdit: string | LiveEffectParameterEdit<E>,
    value?: unknown,
    options: RuntimeParameterOptions = {},
  ): ControlEditSet {
    const normalized = normalizeParameterEdit(keyOrEdit, value, options);
    const row = EFFECT_PARAMETER_ROWS[this.effectId]?.[normalized.key];
    if (row === undefined) {
      throw new MisoUsageError(`${this.effectId} has no parameter '${normalized.key}'`);
    }
    // The value is made a number the frame can hold; whether it is in the row's domain is the
    // core's to say.
    const scalar = parameterScalar(this.effectId, normalized.key, row, normalized.value);
    return this.setRow(
      row.control,
      scalar,
      laneOf(normalized.options.channel),
      rampOptions(normalized.options),
    );
  }

  /**
   * Set or lift this instance's bypass (control `0` of the instance). The core crossfades it on
   * both hosts and refuses what it cannot do.
   */
  bypass(enabled: boolean): ControlEditSet {
    return this.setRow("bypass", flag(enabled), "both");
  }

  /**
   * The link mode of an insert of an effect that has a choice of it. A console slot has no link
   * mode row, and the core refuses the edit.
   */
  linkMode(mode: EffectLinkModeLabel<E>): ControlEditSet {
    const row = EFFECT_LINK_MODE_ROWS[this.effectId];
    if (row === undefined) throw new MisoUsageError(`${this.effectId} has no link mode`);
    return this.setRow(row.control, enumValue(row.choices, mode, `${this.effectId} link mode`), "both");
  }
}

/** One builder of the manifest: where it lives and which rows of the tables it writes. */
export interface ControlBuilderEntry {
  readonly owner: "strip" | "route" | "vca" | "session";
  /** Present for a builder a track has and a submix does not. */
  readonly only?: "track";
  readonly section: "own" | "builtins";
  readonly method: string;
  readonly shape: "row" | "lanePair" | "group";
  readonly valueKind: "number" | "boolean" | "enumeration";
  readonly options: "lane" | "channel" | "smoothing" | "none";
  /** The machine names of the rows it writes, in the order it writes them. */
  readonly rows: readonly string[];
  /** A group builder's argument fields, one per row. */
  readonly fields?: readonly string[];
  readonly choices?: readonly (readonly [string, number])[];
}

